#include <bits/stdc++.h>
using namespace std;
int main(){
    int L,H,R; vector<array<int,3>> bs; int maxX=0;
    while(cin>>L>>H>>R){ bs.push_back({L,H,R}); maxX=max(maxX,R); }
    vector<int> height(maxX+2,0);
    for(auto&t:bs) for(int x=t[0];x<t[2];x++) height[x]=max(height[x],t[1]);
    set<int> edges;
    for(auto&t:bs){ edges.insert(t[0]); edges.insert(t[2]); }
    vector<int> out;
    for(int x: edges){ out.push_back(x); out.push_back(height[x]); }
    for(size_t i=0;i<out.size();i++) cout<<out[i]<<(i+1<out.size()?' ':'\n');
}
